### Problem Type 2: Resilient API Retry Logic
**Description:** Implement a retry mechanism that handles rate limits, transient failures, and API errors with exponential backoff and jitter.

**Key aspects:**
- Distinguish between retryable (429, 503) and non-retryable errors (401, 404)
- Implement exponential backoff with jitter to avoid thundering herd
- Respect `Retry-After` headers from API
- Log appropriately for debugging

```csharp
public class ResilientTranscriptionService
{
    private readonly IOpenAIClient _openAIClient;
    private readonly ILogger<ResilientTranscriptionService> _logger;
    private readonly int _maxRetries = 3;

    public async Task<string> TranscribeWithRetryAsync(
        string audioFilePath,
        CancellationToken cancellationToken = default)
    {
        var retryCount = 0;
        var delay = TimeSpan.FromSeconds(1);

        while (true)
        {
            try
            {
                return await _openAIClient.TranscribeAsync(
                    audioFilePath,
                    cancellationToken
                );
            }
            catch (HttpRequestException ex) when (IsRetryable(ex))
            {
                if (retryCount >= _maxRetries)
                {
                    _logger.LogError($"Max retries exceeded: {ex.Message}");
                    throw;
                }

                // Add jitter to prevent thundering herd
                var jitter = TimeSpan.FromMilliseconds(
                    Random.Shared.Next((int)delay.TotalMilliseconds / 2)
                );
                var waitTime = delay.Add(jitter);

                _logger.LogWarning(
                    $"Retryable error. Attempt {retryCount + 1}/{_maxRetries}. " +
                    $"Waiting {waitTime.TotalSeconds}s"
                );

                await Task.Delay(waitTime, cancellationToken);
                delay = delay.Add(TimeSpan.FromSeconds(delay.TotalSeconds));
                retryCount++;
            }
        }
    }

